#!/usr/bin/env python3
from __future__ import annotations
import base64, gzip, json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PAYLOAD = ""

text = gzip.decompress(base64.b64decode(PAYLOAD)).decode("utf-8")
unit = json.loads(text)
marker = "concepto de la unidad que debe definirse mediante entidades observables"
assert marker not in text.casefold()
assert len(unit["theory_sections"]) == 4
assert len(unit["glossary"]) >= 20
assert len(unit["worked_examples"]) >= 5
assert len(unit["self_assessment"]) >= 10
assert all(s.get("verification_status") == "verified_directly" for s in unit["sources"])
for rel in [
    "data/course_redevelopment/biofotonica/units/unit-01.json",
    "data/generated_units/biofotonica/unit-01.json",
]:
    (ROOT / rel).write_text(json.dumps(unit, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print("Biofotónica U1 curada y espejo sincronizado")
